import os
import csv
import re

def process_logs():
    base_dir = 'loglar'
    results = []

    # loglar klasörünü tara
    for root, dirs, files in os.walk(base_dir):
        for file in files:
            # Sadece .log uzantılı dosyalar (tam eşleşme)
            if file.endswith('.log') and not file.endswith('.log.'):
                file_path = os.path.join(root, file)
                relative_path = os.path.relpath(file_path, base_dir).replace('\\', '/')

                counts = {'ERROR': 0, 'WARN': 0, 'INFO': 0}

                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        for line in f:
                            parts = line.split()
                            # Satır formatı beklentisi: TARİH SAAT SEVİYE mesaj...
                            # 3. alan (index 2) SEVİYE olmalı
                            if len(parts) >= 3:
                                level = parts[2]
                                if level in counts:
                                    counts[level] += 1
                except Exception as e:
                    print(f"Hata okuma ({file_path}): {e}")
                    continue

                results.append({
                    'dosya': relative_path,
                    'error': counts['ERROR'],
                    'warn': counts['WARN'],
                    'info': counts['INFO']
                })

    # Sıralama: error sayısına göre azalan (desc), dosya yoluna göre artan (asc)
    results.sort(key=lambda x: (-x['error'], x['dosya']))

    # CSV oluşturma
    output_file = 'rapor.csv'
    try:
        with open(output_file, 'w', newline='', encoding='utf-8') as csvfile:
            fieldnames = ['dosya', 'error', 'warn', 'info']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            writer.writeheader()
            for row in results:
                writer.writerow(row)
        return f"Başarıyla oluşturuldu: {output_file}"
    except Exception as e:
        return f"CSV yazma hatası: {e}"

print(process_logs())

